mapper.select:
SELECT id, task_id, runner_id, status, assign_time, finish_time, reject_reason, create_time
FROM twelve_runner_order
WHERE task_id = #{taskId}
AND tenant_id = #{tenantId}
ORDER BY assign_time ASC

SELECT id, task_id, runner_id, status, assign_time, finish_time, reject_reason, create_time
FROM twelve_runner_order
WHERE runner_id = #{runnerId}
AND tenant_id = #{tenantId}
AND status = #{status}
ORDER BY assign_time DESC
